/**
 * Lightweight i18n helper for chat UI labels.
 */

// Mirrors the backend's SUPPORTED_LANGUAGES (src/application/i18n/messages.py).
const SUPPORTED_LANGUAGES = new Set(['en', 'fr', 'es', 'it', 'pt', 'de', 'nl']);

function normalizeLanguage(value) {
    const lang = String(value || '').toLowerCase().trim();
    if (SUPPORTED_LANGUAGES.has(lang)) return lang;
    const base = lang.split(/[-_]/, 1)[0];
    if (SUPPORTED_LANGUAGES.has(base)) return base;
    return 'en';
}

function metaContent(name) {
    if (typeof document === 'undefined') return '';
    const el = document.querySelector(`meta[name="${name}"]`);
    return el && el.content ? String(el.content).trim() : '';
}

function browserLanguage() {
    if (typeof navigator === 'undefined') return 'en';
    return normalizeLanguage(navigator.language || 'en');
}

// The server resolves the market (locale → language) and stamps it into a meta
// tag, so the UI starts in the right language on first paint. Falls back to the
// browser language when the meta is absent (legacy render).
function preferredLanguage() {
    const meta = metaContent('du-chat-language');
    if (meta) return normalizeLanguage(meta);
    return browserLanguage();
}

let currentLanguage = preferredLanguage();

